INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('i3y99skuohaekei3y99brzjwusk46a63', '2026-Q3', 'Set/2026 (T3)', '2026-09-19T11:28'::timestamptz, 'Mônica Vargas Abrucese Miranda', 'monica vargas abrucese miranda', 'PHARUS', 'Rodrigo Lunardi', 8.0, 'Neutro', 10.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Não é uma assistência barata e fazendo parte da população com um bom ganho mas com custos altos ,orçamento no limite , mais uma despesa pode influenciar na tomada de decisões , inclusive nos aportes', 'Na verdade , vcs são muito bons , os recursos de quem entra é que não são tão bons para poder investir alto nas propostas que são feitas , ex 50 mil de lance , compra de apartamentos/ studios com m2 muito elevado , enfim , não dá pra entrar em tudo', NULL, 'Não saberia dizer exatamente nesse momento', 'Estamos , eu e meu esposo , felizes de fazermos parte da Quarta via . Sentimos não poderemos aderir a todas as propostas e também  nos gera um pouco de insegurança assumir valores altos na compra de imóveis para se pagar a longo prazo', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'i3y99skuohaekei3y99brzjwusk46a63', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDE